# >>> STATIC
_static_input_scroll_match() {
    cat <<-'ARGCEOF'
	single	error on multiple matches
	first	
ARGCEOF
}

_static_input_text_match() {
    cat <<-'ARGCEOF'
	single	error on multiple matches
	first	
ARGCEOF
}

_static_profiler_heapdump_capture_type() {
    cat <<-'ARGCEOF'
	hprof	default; may change in a future release
	perfetto	
ARGCEOF
}

_static_screen_capture_distance() {
    cat <<-'ARGCEOF'
	MIN_EUCLIDEAN	
	MIN_ANISOTROPIC	weights vertical separation on the y-axis more heavily than horizontal separation on the x-axis
ARGCEOF
}

_static_screen_capture_features() {
    cat <<-'ARGCEOF'
	GREEDY	combines shapes closer than --threshold distance into a single feature
	FH	uses --threshold as the segmentation scale parameter, where higher values produce fewer, larger features and lower values produce more, smaller features
ARGCEOF
}

_static_studio_version_lookup_artifacts() {
    cat <<-'ARGCEOF'
	groupId:artifactId	for Maven libraries, such as androidx.window:window
	pluginId	for Gradle plugins, such as com.android.application
	gradle	for the Gradle build tool
	studio	for Android Studio
	agp	for Android Gradle plugin
	ndk	for the Android NDK
	sdk	for the Android SDK
	emulator	for the Android Emulator
	adb	for the Android Debug Bridge (ADB)
	compose	for the Compose BOM
	kotlin	for the Kotlin language and runtime
	android	for Android versions
	platform-tools	for Android SDK Platform-Tools
	cmdline-tools	for Android SDK Command-line Tools
	build-tools	for Android SDK Build-Tools
ARGCEOF
}
