# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_any_path() { _argc_util_comp_path; }

_choice_api_level() { _helper_crash_facets api-level; }

_choice_apk_path() { _argc_util_comp_path exts=.apk; }

_choice_app_package() { _argc_util_cache 60 _choice_app_package_uncached app-packages; }

_choice_app_package_uncached() {
    adb shell pm list packages 2>/dev/null | gawk -F: '/^package:/ { print $2 }'
}

_choice_app_version() { _helper_crash_facets app-version; }

_choice_avd() {
    android emulator list 2>/dev/null | gawk 'NF && $1 !~ /^(Name|AVD|ID|Installed|Available|No|The|Emulator)/ { print $1 }'
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 3 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_device() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    adb devices 2>/dev/null | gawk 'NR > 1 && $2 == "device" { print $1 }'
    android emulator list 2>/dev/null | gawk 'NF && $1 !~ /^(Name|AVD|ID|Installed|Available|No|The|Emulator)/ { print $1 }'
}

_choice_device_filter() { _helper_crash_facets device; }

_choice_firebase() {
    android signals context 2>/dev/null | gawk 'NF && $1 !~ /^(Error|No|Make|Please|Available|Firebase|Projects|Project)/ { print $1 }'
}

_choice_gcp_project() {
    android device remote projects 2>/dev/null | gawk 'NF && $1 !~ /^(Error|No|Make|Please|Available|Projects|Project)/ { print $1 }'
}

_choice_heap() {
    android signals heaps list 2>/dev/null | gawk 'NF && $1 ~ /^[a-z]+\// { print $1 }'
}

_choice_issue() {
    android signals crashes list 2>/dev/null | gawk 'NF && $1 ~ /^[a-z]+\// { print $1 }'
}

_choice_key() {
    printf '%s\n' back home recents power volume-up volume-down enter tab esc
}

_choice_match() { printf '%s\n' single first; }

_choice_package() {
    android sdk list 2>/dev/null | gawk 'NF && $1 !~ /^(Installed|Available|Error|No|Package|Packages|\()/ { print $1 }'
}

_choice_profile() { android emulator create --list-profiles 2>/dev/null; }

_choice_remote_model() {
    android device remote models 2>/dev/null | gawk 'NF && $1 !~ /^(Error|No|Make|Please|Available|Model|Models)/ { print $1 }'
}

_choice_reservation() {
    android device remote list 2>/dev/null | gawk 'NF && $1 !~ /^(Error|No|Make|Please|Available|ID|Reservation)/ { print $1 }'
}

_choice_sample() {
    local issue="${argc_issue_id:-}"
    [[ -n "$issue" ]] || return 0
    android signals crashes samples "$issue" 2>/dev/null | gawk 'NF && $1 ~ /^[a-z]+\// { print $1 }'
}

_choice_sdk() { _argc_util_comp_path dir; }

_choice_session() {
    android profiler session list 2>/dev/null | gawk 'NF && $1 !~ /^(Total|Session|ID|No|Active)/ { print $1 }'
}

_choice_skill() { _argc_util_cache 3600 _choice_skill_uncached skills; }

_choice_skill_uncached() {
    android skills list 2>/dev/null | gawk 'NF == 1 && $1 ~ /^[a-z][a-z0-9-]*$/ { print $1 }'
}

_choice_studio_pid() {
    android studio check 2>/dev/null | gawk 'match($0, /[0-9]+/) { print substr($0, RSTART, RLENGTH) }'
}

_choice_studio_project() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    android studio check 2>/dev/null | gawk 'NF && $1 !~ /^(No|Make|Download|Error)/ { print $1 }'
}

_choice_template() { _argc_util_cache 3600 _choice_template_uncached templates; }

_choice_template_uncached() {
    android create --list 2>/dev/null | gawk 'NF && $1 !~ /^(Template|https|Unzipping|Error|No)/ { print $1 }'
}

_helper_crash_facets() {
    local app="${argc_firebase_app:-}"
    [[ -n "$app" ]] || return 0
    android signals crashes facets --firebase-app "$app" "$1" 2>/dev/null | gawk 'NF { print $1 }'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
